static float dist = q11;
static float mouth_y = q3;
vec2 rs (vec2 uv_in) {
uv_in.x += q9;
return  uv_in*dist*(.4+clamp(abs(uv_in.x),-1/dist,1.0 / dist) + 4.0*q9*uv_in.x)-.5+vec2( 0.0 ,q10+mouth_y);}
vec2 rs2 (vec2 uv_in) {
uv_in.x += q9*.96 ;
tmp = uv_in*1.1*dist*(.4+clamp(abs(uv_in.x),-1/dist,1.0 / dist) + 4.0*q9*uv_in.x)-.5+vec2( 0.0 ,q10*.96+mouth_y);
