  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec2 uv4 = uv-.5+vec2(q9,q10);
float water = texture(sampler_noise_mq,uv / 2.0+uTime / 5.0);
uv1 = (uv-.5)*uAspect.xy + water *.0;
uv3 = rs(uv1);
float rad1 = clamp01(.2/dist/length(uv1.x+q9));
float rad2 = clamp01(.05/dist/length(uv1+vec2(q9,q10)));
beast = texture(sampler_main, uv3)*rad1;
bcopy = texture(sampler_main, rs2(uv1))*clamp01(1-8*lum(beast))*rad2 / 2.0;;
float light = 2.0 * clamp01(.05/length(uv1+lightpos + 2.0*dz(uv3)));
float flatlight = clamp01((1.0 + q15)*.5/dist/length(uv1+lightpos));
vec2 uv5 = normalize(uv1+vec2(.1,.1)+lightpos) * 1.0+lightpos;
vec3 ray = clamp01(GetPixel(rs(uv5)));
beast *= pow(flatlight, 2.0 )*.7;
beast += lum(beast)*light*light *pow(flatlight, 2.0 ) ;
//beast = mix(beast,.2*vec3(.5,.5, 1.0)*flatlight,4.0 * abs(uv1.x));
ret = (beast+bcopy*flatlight);
ret = mix(clamp01(flatlight*vec3(q22, 0.0 , 0.0)),ret, vis);
  fragColor = vec4(ret, 1.0);
}

